package com.bananalab.lite;
import java.io.*;import org.json.*;
public class Stage37ModelsCheck{
 public static void main(String[] args)throws Exception{String r=args[0],candidate=r+"/model-source/chat35-candidate/";BananaTransformer model=new BananaTransformer(new FileInputStream(candidate+"chat35.bin"),new FileInputStream(candidate+"vocab.txt"),new FileInputStream(candidate+"tokenizer.json"));float max=0;try(DataInputStream in=new DataInputStream(new FileInputStream(r+"/model-source/chat35-reference.bin"))){int cases=in.readInt(),v=in.readInt();for(int c=0;c<cases;c++){int n=in.readInt();BananaTransformer.Session s=model.session();float[] actual=null;for(int i=0;i<n;i++)actual=s.step(in.readInt());for(int i=0;i<v;i++)max=Math.max(max,Math.abs(actual[i]-in.readFloat()));}}if(max>.0005)throw new AssertionError("candidate parity "+max);JSONObject card=new JSONObject(new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(candidate+"model-card.json")),"UTF-8"));if(card.getBoolean("external_weights")||card.getBoolean("external_teacher")||card.getBoolean("promoted"))throw new AssertionError("training provenance or promotion gate");System.out.println("PASS own checkpoint candidate parity "+max+"; kept out of active model after held-out quality review");}
}
